@@ -705,3 +705,19 @@
 	r := startCLI(t, w, nil, nil, "run").result()
 	expectRefusal(t, r, nil, "loop", "invalid_task", 2)
 }
+
+// TestHelpAndUsage exercises standalone help and the adjacent invalid forms offline.
+func TestHelpAndUsage(t *testing.T) {
+	t.Parallel()
+	const usage = "usage: kogen-loop capabilities --json | version | run --task FILE|-\n"
+	for _, arg := range []string{"--help", "-h", "help"} {
+		t.Run(arg, func(t *testing.T) {
+			if out, code := runPlain(t, arg); code != 0 || out != usage {
+				t.Errorf("%s: exit %d stdout %q, want exit 0 stdout %q", arg, code, out, usage)
+			}
+			if out, code := runPlain(t, arg, "extra"); code != 2 || out != "" {
+				t.Errorf("%s extra: exit %d stdout %q, want exit 2 and empty stdout", arg, code, out)
+			}
+		})
+	}
+}

